---

### 📌 C++ Code Example

```cpp
#include <wx/wx.h>
#include <wx/grid.h>

// Function to get cell value by column label string and row index
wxString GetCellValueByColumnLabel(wxGrid* grid, int rowIndex, const wxString& colLabel)
{
    if (!grid || rowIndex < 0 || rowIndex >= grid->GetNumberRows())
        return wxEmptyString;

    // Search for the column index matching the label
    int colIndex = -1;
    int numCols = grid->GetNumberCols();
    for (int col = 0; col < numCols; ++col)
    {
        if (grid->GetColLabelValue(col) == colLabel)
        {
            colIndex = col;
            break;
        }
    }

    // If column not found, return empty string
    if (colIndex == -1)
        return wxEmptyString;

    // Return the cell value at (rowIndex, colIndex)
    return grid->GetCellValue(rowIndex, colIndex);
}
```

---

