### 🚀 Optional: Cache Column Indices for Better Performance

If you're querying the same grid repeatedly, pre-build a map:

```cpp
class GridHelper
{
private:
    wxGrid* m_grid;
    wxHashMap<wxString, int> m_colMap;

public:
    GridHelper(wxGrid* grid) : m_grid(grid)
    {
        BuildColumnMap();
    }

    void BuildColumnMap()
    {
        m_colMap.Clear();
        for (int col = 0; col < m_grid->GetNumberCols(); ++col)
        {
            wxString label = m_grid->GetColLabelValue(col);
            m_colMap[label] = col;
        }
    }

    wxString GetValue(int rowIndex, const wxString& colLabel)
    {
        int* colIndex = m_colMap.Find(colLabel);
        if (!colIndex || rowIndex < 0 || rowIndex >= m_grid->GetNumberRows())
            return wxEmptyString;
        return m_grid->GetCellValue(rowIndex, *colIndex);
    }
};
```

