    // Check if array is actually an array
    if (!Array.isArray(array)) {
        return false;
    }

    // Method 1: Using indexOf (strict equality comparison)
    // This will return -1 if element is not found or type doesn't match
    const index = array.indexOf(searchElement);
    const foundWithStrictEquality = index !== -1;

    // Method 2: Using includes (strict equality comparison)
    const foundWithIncludes = array.includes(searchElement);

    // Method 3: Using some with type coercion comparison (loose equality)
    const foundWithLooseEquality = array.some(element => element == searchElement);

    // Method 4: Using some with strict equality comparison
    const foundWithStrictComparison = array.some(element => element === searchElement);

    // Return results with detailed information
    return {
        array: array,
        searchElement: searchElement,
        searchElementType: typeof searchElement,
        arrayElementTypes: array.map(element => typeof element),
        foundWithStrictEquality: foundWithStrictEquality,
        foundWithIncludes: foundWithIncludes,
        foundWithLooseEquality: foundWithLooseEquality,
        foundWithStrictComparison: foundWithStrictComparison,
        indexOfElement: index,
        countOfOccurrences: array.filter(element => element === searchElement).length,
        countOfLooseMatches: array.filter(element => element == searchElement).length,
        message: foundWithStrictEquality ? 
            `Element "${searchElement}" found in array (strict equality)` : 
            `Element "${searchElement}" NOT found in array (strict equality - type mismatch)`
    };
}

